import {bindSkillPicker} from './curriculum';
import {dataStorage,flushStorage} from './storage';
import {editorTypes, generatorTypes, getEditorType, labelType, seriesOf, generatorDefaults, generatorInfo, generateSpecial, type EditorType, type GeneratorInput} from './question-types';
import {generateWordSearch,normalizeWords,puzzleMarkup,type WordPuzzle} from './word-search';
export type Question={id:string;sourceId:string;sourceName:string;number:string;component:'english'|'life-project'|'general';grade:string;topic:string;kind:string;html:string;context:string;answer:string;reviewed:boolean;updatedAt:string;name?:string;skill?:string;filters?:string[];correct?:string;justification?:string;columns?:number;gap?:number;divider?:boolean;columnWidth?:number;structured?:boolean;editorType?:EditorType;series?:string[];schoolMode?:string;generatorData?:string;responseLines?:number;curriculumIds?:string[];curriculumObjects?:string[]};
const endpoint='/.netlify/functions/question-bank';
async function api(body?:unknown){const r=await fetch(endpoint,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),credentials:'same-origin'}:{cache:'no-store',credentials:'same-origin'});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||'Banco de questões indisponível.');return j;}
export const indexQuestions=async(id:string):Promise<number>=>(await api({action:'extract',id})).added;
const cacheKey='marks-class-studio:question-cache:v10',pendingKey='marks-class-studio:question-pending:v10';
const readRows=(key:string):Question[]=>{try{return JSON.parse(dataStorage.getItem(key)||'[]');}catch{return [];}};
export const localQuestions=()=>readRows(cacheKey);
const pendingQuestions=()=>readRows(pendingKey);
function writeRows(key:string,rows:Question[]){dataStorage.setItem(key,JSON.stringify(rows));}
function putLocal(q:Question,pending=true){writeRows(cacheKey,[q,...localQuestions().filter(x=>x.id!==q.id)]);if(pending)writeRows(pendingKey,[q,...pendingQuestions().filter(x=>x.id!==q.id)]);}
let syncFlight:Promise<void>|null=null;
async function syncPending(){if(syncFlight)return syncFlight;syncFlight=(async()=>{for(const q of pendingQuestions()){const result=await api({...q,action:'save',restore:true});if(result.deleted){writeRows(cacheKey,localQuestions().filter(x=>x.id!==q.id));writeRows(pendingKey,pendingQuestions().filter(x=>x.id!==q.id));continue;}const latest=pendingQuestions().find(x=>x.id===q.id);if(latest&&JSON.stringify(latest)===JSON.stringify(q)){writeRows(pendingKey,pendingQuestions().filter(x=>x.id!==q.id));putLocal(result.data,false);}}})().finally(()=>syncFlight=null);return syncFlight;}
export async function exportQuestions():Promise<Question[]>{await syncPending();const remote:Question[]=(await api()).data;const pending=pendingQuestions();const rows=[...remote.filter(q=>!pending.some(p=>p.id===q.id)),...pending];writeRows(cacheKey,rows);return rows;}

export async function importQuestions(rows:unknown,sanitize:(s:string)=>string){if(rows===undefined)return;if(!Array.isArray(rows))throw new Error('Banco de questões inválido no backup.');for(const q of rows){if(!q||typeof q.id!=='string'||! /^[\w-]{1,100}$/.test(q.id)||typeof q.html!=='string'||!q.html.trim())throw new Error('Questão inválida no backup.');const restored={...q,html:sanitize(q.html)} as Question;putLocal(restored);await syncPending();}}
const el=<T extends HTMLElement=HTMLElement>(id:string)=>document.getElementById(id) as T;
const norm=(s:string)=>s.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase();
const error=(e:unknown)=>e instanceof Error?e.message:String(e);
const options=(rows:string[])=>rows.map(x=>`<option>${esc(x)}</option>`).join('');
const text=(html:string)=>new DOMParser().parseFromString(html,'text/html').body.textContent||'';
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c));
export const FILTER_PREF='mcs-question-filters-v11';
export type CustomFilter={name:string;aliases:string};
export function questionFilters():CustomFilter[]{try{const a=JSON.parse(dataStorage.getItem(FILTER_PREF)||'[]');return Array.isArray(a)?a.filter(x=>typeof x?.name==='string'&&typeof x?.aliases==='string').slice(0,300):[];}catch{return [];}}
const bilingualGroups=['food,alimentação,alimento,comida,meal,refeição','dream,sonho','future,futuro','goal,meta,objetivo,aim','choice,escolha,decision,decisão','life,vida','reading,leitura,interpretação,comprehension,compreensão','listening,escuta,audição','writing,escrita,produção textual','grammar,gramática','vocabulary,vocabulário','verb,verbo','past,passado','present,presente','school,escola','family,família','work,trabalho,job,emprego','health,saúde','environment,meio ambiente','emotion,emoção,sentimento,feeling','planning,planejamento','respect,respeito','friendship,amizade','identity,identidade','diversity,diversidade','travel,viagem','time,tempo','music,música','sports,esporte','water,água','technology,tecnologia','education,educação','question,questão,pergunta','word search,caça-palavras','fill in the blanks,lacunas','matching,associação','responsibility,responsabilidade','autonomy,autonomia','citizenship,cidadania','resilience,resiliência','happiness,felicidade','success,sucesso'];
export function matchesQuestion(q:Question,query:string){const hay=norm([q.name,q.topic,q.skill,q.grade,q.sourceName,q.kind,labelType(getEditorType(q)),q.schoolMode,...seriesOf(q),...(q.filters||[]),text(q.html),q.context,q.answer,q.justification].filter(Boolean).join(' '));const groups=[...bilingualGroups.map(x=>x.split(',')),...questionFilters().map(x=>[x.name,...x.aliases.split(/[,;\n]/)])].map(g=>g.map(x=>norm(x.trim())).filter(Boolean));const tokens=norm(query).trim().split(/\s+/).filter(Boolean);return tokens.every(t=>hay.includes(t)||groups.some(g=>g.some(v=>v===t||v.split(' ').includes(t))&&g.some(v=>hay.includes(v))));}
export function questionAnswer(q:Question,commented=true){const answer=q.correct?`${q.correct})${q.answer?' '+q.answer:''}`:q.answer||'Resposta não cadastrada';return answer+(commented&&q.justification?' — '+q.justification:'');}
// Number the first real text run, including pasted nested divs and inline formatting.
export function questionMarkup(qs:Question[],start:number,includeContext:boolean,numbered:boolean,sanitize:(s:string)=>string){
 const contexts=new Set<string>();return qs.map((q,i)=>{let context='';if(includeContext&&q.context.trim()&&!contexts.has(q.context)){contexts.add(q.context);context=q.context.split(/\n/).map(x=>`<p>${esc(x)||'<br>'}</p>`).join('');}
 const doc=new DOMParser().parseFromString(sanitize(q.html),'text/html');
 if(numbered){
  const prefix=doc.createElement('strong');prefix.className='qb-number';prefix.textContent=`${start+i}. `;
  const candidates=[doc.body.querySelector('.qb-part-prompt'),doc.body.querySelector('.qb-part-command'),doc.body.querySelector('.qb-part-text'),doc.body];
  let placed=false;
  for(const root of candidates){if(!root)continue;const walker=doc.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node:Node|null;
   while((node=walker.nextNode())){if(!node.textContent?.trim()||node.parentElement?.closest('script,style,table,.qb-part-alternatives,.qb-part-generated,.qb-part-lines,[hidden]'))continue;
    // Keep prefix in the same inline formatting context as the first visible character.
    node.textContent=node.textContent.replace(/^[\s\u00a0]+/,'');node.parentNode!.insertBefore(prefix,node);placed=true;break;}
   if(placed)break;
  }
  if(!placed){const p=doc.createElement('p');p.append(prefix);const target=doc.body.querySelector('.qb-part-prompt')||doc.body.querySelector('.qb-structured')||doc.body;target.prepend(p);}
 }
 return `<div class="qb-question-block" style="font-family:Arial,sans-serif;font-size:12pt;line-height:1.15;text-align:justify;margin:0 0 3pt">${context}${doc.body.innerHTML}</div>`;}).join('');
}

