 let filterEditing='';function updateFilterOptions(){const old=val('qbCustomFilter');const tags=[...el<HTMLSelectElement>('qbTags').selectedOptions].map(o=>o.value);el('qbCustomFilter').innerHTML='<option value="">Todos os filtros</option>'+options(questionFilters().map(f=>f.name));el<HTMLSelectElement>('qbCustomFilter').value=old; if(!el<HTMLSelectElement>('qbCustomFilter').value)el<HTMLSelectElement>('qbCustomFilter').value='';el('qbTags').innerHTML=options([...new Set([...questionFilters().map(f=>f.name),...tags])]);for(const o of el<HTMLSelectElement>('qbTags').options)o.selected=tags.includes(o.value);}
 function setFilters(f:CustomFilter[]){dataStorage.setItem(FILTER_PREF,JSON.stringify(f));opts.filtersChanged();updateFilterOptions();paintFilterList();paint();}
 function resetFilter(){filterEditing='';el<HTMLInputElement>('qbFilterName').value='';el<HTMLTextAreaElement>('qbFilterAliases').value='';}
 function paintFilterList(){const mount=el('qbFilterList');mount.replaceChildren();for(const f of questionFilters()){const row=document.createElement('article');row.className='library-card';const info=document.createElement('div');info.textContent=f.name;const edit=document.createElement('button');edit.textContent='Editar';edit.onclick=()=>{filterEditing=f.name;el<HTMLInputElement>('qbFilterName').value=f.name;el<HTMLTextAreaElement>('qbFilterAliases').value=f.aliases;};const del=document.createElement('button');del.textContent='Excluir';del.onclick=()=>{if(confirm('Remover filtro da lista? As questões existentes conservarão suas etiquetas.'))setFilters(questionFilters().filter(x=>x.name!==f.name));};row.append(info,edit,del);mount.append(row);}}
